<script>
(function(){
  const N = 12;
  const weights = [0.3, 0.8, 0.5, 1.2, 0.4, 2.5, 0.7, 0.3, 1.8, 0.6, 0.4, 1.5];
  let idx = 0, wsum = 0, chosen = -1, timer = null;
  const svg = document.getElementById('wrs-canvas');
  const info = document.getElementById('wrs-info');
  function render() {
    const barW = 40, gap = 14, baseY = 200, maxW = 2.5;
    let html = '';
    html += `<line x1="20" y1="${baseY}" x2="700" y2="${baseY}" stroke="#888" stroke-width="1"/>`;
    html += `<text x="20" y="225" font-size="11" fill="#999">samples →</text>`;
    for (let i = 0; i < N; i++) {
      const x = 30 + i * (barW + gap);
      const barH = (weights[i] / maxW) * 160;
      let fill = '#bbb', stroke = '#888';
      if (i < idx) { fill = '#a0d8ff'; stroke = '#1890ff'; }
      if (i === chosen) { fill = '#ffd591'; stroke = '#fa541c'; }
      html += `<rect x="${x}" y="${baseY - barH}" width="${barW}" height="${barH}" fill="${fill}" stroke="${stroke}" stroke-width="${i===chosen?3:1}" rx="2"/>`;
      html += `<text x="${x+barW/2}" y="${baseY-barH-5}" font-size="10" text-anchor="middle" fill="#555">${weights[i]}</text>`;
      html += `<text x="${x+barW/2}" y="${baseY+15}" font-size="10" text-anchor="middle" fill="${i===chosen?'#fa541c':'#888'}" font-weight="${i===chosen?700:400}">X${i+1}</text>`;
    }
    if (chosen >= 0) {
      const x = 30 + chosen * (barW + gap) + barW/2;
      html += `<text x="${x}" y="40" font-size="12" text-anchor="middle" fill="#fa541c" font-weight="700">⬇ Reservoir.Y</text>`;
