      <button id="ris-pick100" style="background:#52c41a;color:#fff;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;margin-right:6px;">Resample ×100</button>
      <button id="ris-clear" style="background:#999;color:#fff;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">Clear Hist</button>
    </div>
  </div>
  <svg id="ris-canvas" viewBox="0 0 720 280" xmlns="http://www.w3.org/2000/svg" style="width:100%;background:#fff;border-radius:4px;border:1px solid #eee;"></svg>
  <div id="ris-info" style="margin-top:10px;font-size:12px;color:#555;font-family:'SF Mono',Consolas,monospace;background:#f5f5f5;padding:10px;border-radius:4px;">
    M=16 candidates uniformly sampled. Resample count: 0
  </div>
</div>
<script>
(function(){
  const M = 16;
  const W_DOMAIN = 720;
  let candidates = [];
  let histogram = new Array(40).fill(0);
  let totalPicks = 0;
  const svg = document.getElementById('ris-canvas');
  const info = document.getElementById('ris-info');
  function pHat(x) {
    return 0.6 * Math.exp(-Math.pow((x-0.3)*8, 2)) + 1.0 * Math.exp(-Math.pow((x-0.75)*10, 2)) + 0.05;
  }
  function regenerateCandidates() {
    candidates = [];
    for (let i = 0; i < M; i++) {
      const x = Math.random();
      const ph = pHat(x);
      const w = (1.0/M) * ph / 1.0;
      candidates.push({x, ph, w});
    }
  }
  function pickOnce() {
    let wsum = 0;
    for (const c of candidates) wsum += c.w;
    let r = Math.random() * wsum;
    let chosen = candidates[0];
    for (const c of candidates) { r -= c.w; if (r <= 0) { chosen = c; break; } }
    const bin = Math.min(39, Math.floor(chosen.x * 40));
    histogram[bin]++; totalPicks++;
    return chosen;
  }
  function render(highlightX = -1) {
    const margin = 30;
    const plotW = W_DOMAIN - 2*margin;
    const plotH = 200;
    let html = '';
    html += `<line x1="${margin}" y1="${margin+plotH}" x2="${margin+plotW}" y2="${margin+plotH}" stroke="#888"/>`;
    html += `<line x1="${margin}" y1="${margin}" x2="${margin}" y2="${margin+plotH}" stroke="#888"/>`;
    let path = `M ${margin} ${margin+plotH}`;
    let maxPh = 0;
    for (let i = 0; i <= 100; i++) maxPh = Math.max(maxPh, pHat(i/100));
    for (let i = 0; i <= 100; i++) {
      const x = i / 100;
      const ph = pHat(x);
      const px = margin + x * plotW;
      const py = margin + plotH - (ph/maxPh) * plotH * 0.85;
      path += ` L ${px} ${py}`;
    }
    html += `<path d="${path}" stroke="#fa541c" stroke-width="2" fill="none"/>`;
    html += `<text x="${margin+5}" y="${margin+15}" font-size="11" fill="#fa541c" font-weight="600">p̂(x) target</text>`;
    let maxW = 0;
    for (const c of candidates) maxW = Math.max(maxW, c.w);
    for (const c of candidates) {
      const px = margin + c.x * plotW;
      const barH = (c.w / maxW) * plotH * 0.6;
      const isHL = (highlightX >= 0 && Math.abs(c.x - highlightX) < 0.001);
      html += `<line x1="${px}" y1="${margin+plotH}" x2="${px}" y2="${margin+plotH-barH}" stroke="${isHL?'#fa8c16':'#1890ff'}" stroke-width="${isHL?4:2}" opacity="${isHL?1:0.6}"/>`;
      html += `<circle cx="${px}" cy="${margin+plotH-barH}" r="${isHL?5:3}" fill="${isHL?'#fa8c16':'#1890ff'}"/>`;
    }
    html += `<text x="${margin+5}" y="${margin+30}" font-size="11" fill="#1890ff" font-weight="600">candidates (height = w_i)</text>`;
    const histY = margin + plotH + 25;
    const histH = 35;
    const maxBin = Math.max(1, ...histogram);
    html += `<text x="${margin+5}" y="${histY-3}" font-size="11" fill="#52c41a" font-weight="600">empirical distribution after resampling (${totalPicks} picks)</text>`;
    for (let i = 0; i < 40; i++) {
      const bx = margin + (i/40) * plotW;
      const bw = plotW / 40 - 1;
      const bh = (histogram[i] / maxBin) * histH;
      html += `<rect x="${bx}" y="${histY+histH-bh}" width="${bw}" height="${bh}" fill="#52c41a" opacity="0.7"/>`;
    }
    svg.innerHTML = html;
  }
  document.getElementById('ris-new').onclick = function(){ regenerateCandidates(); render(); info.textContent = `M=${M} candidates uniformly sampled. Resample count: ${totalPicks}`; };
  document.getElementById('ris-pick').onclick = function(){ const c = pickOnce(); render(c.x); info.textContent = `Picked X=${c.x.toFixed(3)} (w=${c.w.toFixed(4)}, p̂=${c.ph.toFixed(3)}). Total: ${totalPicks}`; };
  document.getElementById('ris-pick100').onclick = function(){ for (let i = 0; i < 100; i++) pickOnce(); render(); info.textContent = `+100 picks. Total: ${totalPicks}. Histogram should approximate normalized p̂.`; };
  document.getElementById('ris-clear').onclick = function(){ histogram.fill(0); totalPicks = 0; render(); info.textContent = 'Histogram cleared.'; };
  regenerateCandidates(); render();
})();
</script>
