```c
// 论文配套实现常用的 clipping table 思路
int n = 0;
if (L[0].z > 0.0) L_clipped[n++] = L[0];
if (L[1].z > 0.0) {
    if (L[0].z <= 0.0) L_clipped[n++] = (L[0]*L[1].z - L[1]*L[0].z) / (L[1].z - L[0].z);
    L_clipped[n++] = L[1];
} else if (L[0].z > 0.0) {
    L_clipped[n++] = (L[0]*L[1].z - L[1]*L[0].z) / (L[1].z - L[0].z);
}
// ... 对 L[2], L[3] 重复
```

