<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

(function initLTCWidget() {
  const host = document.getElementById('ltc-canvas-host');
  if (!host) return;

  const W = () => host.clientWidth;
  const H = () => host.clientHeight;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8fafc);

  const camera = new THREE.PerspectiveCamera(40, W() / H(), 0.1, 100);
  camera.up.set(0, 0, 1);
  camera.position.set(2.8, -3.2, 2.4);
  camera.lookAt(0.3, 0, 0.3);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.setSize(W(), H());
  host.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.minDistance = 1.8;
  controls.maxDistance = 10.0;

  // === 1. 单位球（分布染色） ===
  const SUBDIV = 96;
  const sphereGeom = new THREE.SphereGeometry(1, SUBDIV, SUBDIV / 2);
  sphereGeom.rotateX(Math.PI / 2);
  const positionsRef = sphereGeom.attributes.position.array.slice();
  const colors = new Float32Array(positionsRef.length);
  sphereGeom.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const sphereMat = new THREE.MeshBasicMaterial({
    vertexColors: true,
    side: THREE.FrontSide
  });
  const sphere = new THREE.Mesh(sphereGeom, sphereMat);
  scene.add(sphere);

  const outlineGeom = new THREE.SphereGeometry(1.002, 64, 32);
  outlineGeom.rotateX(Math.PI / 2);
  const outlineMat = new THREE.MeshBasicMaterial({
    color: 0x94a3b8, side: THREE.BackSide, transparent: true, opacity: 0.15
  });
  scene.add(new THREE.Mesh(outlineGeom, outlineMat));

  // === 2. 主导方向射线 (1根中心 + 4根对角线) ===
  const NUM_SAMPLES = 5;
  const sinT = 0.36; // 控制边缘射线的张角
  const cosT = Math.sqrt(1 - sinT * sinT);

  // 使用对角线排布，以便与四边形光源的 4 个顶点完美对齐
  const cosineSamples = [
    new THREE.Vector3(0, 0, 1),
    new THREE.Vector3( sinT,  sinT, cosT).normalize(),
    new THREE.Vector3(-sinT,  sinT, cosT).normalize(),
    new THREE.Vector3(-sinT, -sinT, cosT).normalize(),
    new THREE.Vector3( sinT, -sinT, cosT).normalize()
  ];

  const lineMat = new THREE.LineBasicMaterial({
    color: 0x111111, depthTest: false, depthWrite: false, transparent: true, opacity: 0.95
  });
  const sampleLines = [];
  const sampleDots = [];
  const dotGeom = new THREE.SphereGeometry(0.028, 12, 12);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0x111111, depthTest: false, depthWrite: false });

  for (let i = 0; i < NUM_SAMPLES; i++) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
    const line = new THREE.Line(g, lineMat);
    line.renderOrder = 10;
    scene.add(line);
    sampleLines.push(line);

    const dot = new THREE.Mesh(dotGeom, dotMat);
    dot.renderOrder = 11;
    scene.add(dot);
    sampleDots.push(dot);
  }

  // === 3. 面光源 (红色四边形与立体角连线) ===
  const baseZ = 1.7; // 四边形所处的高度
  const extent = baseZ * (sinT / cosT); // 精确计算，使其角落恰好落在射线上

  const lightBasePoints = [
    new THREE.Vector3( extent,  extent, baseZ), // Top-Right
    new THREE.Vector3(-extent,  extent, baseZ), // Top-Left
    new THREE.Vector3(-extent, -extent, baseZ), // Bottom-Left
    new THREE.Vector3( extent, -extent, baseZ)  // Bottom-Right
  ];

  // 面光源 Mesh
  const lightGeom = new THREE.BufferGeometry();
  lightGeom.setIndex([0, 1, 2, 0, 2, 3]);
  lightGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(12), 3));
  const lightMat = new THREE.MeshBasicMaterial({
    color: 0xef4444, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false
  });
  const lightMesh = new THREE.Mesh(lightGeom, lightMat);
  lightMesh.renderOrder = 5;
  scene.add(lightMesh);

  // 面光源边框
  const lightEdgesGeom = new THREE.BufferGeometry();
  lightEdgesGeom.setIndex([0, 1, 1, 2, 2, 3, 3, 0]);
  lightEdgesGeom.setAttribute('position', lightGeom.attributes.position); // 共享顶点
  const lightEdgesMat = new THREE.LineBasicMaterial({ color: 0x111111, linewidth: 1.5 });
  const lightEdges = new THREE.LineSegments(lightEdgesGeom, lightEdgesMat);
  scene.add(lightEdges);

  // 面光源到原点的连线 (表示立体角)
  const connLines = [];
  const connMat = new THREE.LineBasicMaterial({ color: 0x111111, transparent: true, opacity: 0.4 });
  for (let i = 0; i < 4; i++) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
    const line = new THREE.Line(g, connMat);
    scene.add(line);
    connLines.push(line);
  }

  // === 4. 被 M 变形的红色参考方块 ===
  const CUBE_SIZE = 0.42;
  const cubeGeom = new THREE.BoxGeometry(CUBE_SIZE, CUBE_SIZE, CUBE_SIZE);
  const cubeRef = cubeGeom.attributes.position.array.slice();
  const cubeMat = new THREE.MeshBasicMaterial({ color: 0xc92626, transparent: true, opacity: 0.55 });
  const cubeEdgesMat = new THREE.LineBasicMaterial({ color: 0x7a1818, linewidth: 1.5 });

  const cube = new THREE.Mesh(cubeGeom, cubeMat);
  const cubeAnchor = new THREE.Vector3(1.7, -0.4, -0.6);
  cube.position.copy(cubeAnchor);
  scene.add(cube);

  let cubeEdges = new THREE.LineSegments(new THREE.EdgesGeometry(cubeGeom), cubeEdgesMat);
  cubeEdges.position.copy(cubeAnchor);
  scene.add(cubeEdges);

  // ----- 核心状态 -----
  const state = { sxx: 1.0, syy: 1.0, mxz: 0.0, myz: 0.0 };

  // ----- 数学与着色函数 -----
  function colormap(t) {
    t = Math.max(0, Math.min(1, t));
    const stops = [
      [0.231, 0.298, 0.753], [0.435, 0.553, 0.890], [0.706, 0.804, 0.937],
      [0.965, 0.945, 0.918], [0.957, 0.647, 0.510], [0.890, 0.318, 0.247],
      [0.706, 0.016, 0.149]
    ];
    const seg = t * (stops.length - 1);
    const i = Math.floor(seg);
    const f = seg - i;
    const a = stops[Math.min(i, stops.length - 1)];
    const b = stops[Math.min(i + 1, stops.length - 1)];
    return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f];
  }

  function buildInvM() {
    const sxx = state.sxx, syy = state.syy, mxz = state.mxz, myz = state.myz;
    return {
      a: 1 / sxx, b: 0, c: -mxz / sxx,
      d: 0, e: 1 / syy, f: -myz / syy,
      g: 0, h: 0, i: 1, detInv: 1.0 / (sxx * syy)
    };
  }

  function evalLTC(wx, wy, wz, M) {
    const ox = M.a * wx + M.b * wy + M.c * wz;
    const oy = M.d * wx + M.e * wy + M.f * wz;
    const oz = M.g * wx + M.h * wy + M.i * wz;
    const len = Math.sqrt(ox * ox + oy * oy + oz * oz);
    if (len < 1e-6) return 0;
    const cosT = oz / len;
    if (cosT <= 0) return 0;
    return (cosT / Math.PI) * Math.abs(M.detInv) / (len * len * len);
  }

  // 变换并归一化 (用于射线)
  function applyM(dir) {
    const sxx = state.sxx, syy = state.syy, mxz = state.mxz, myz = state.myz;
    const x = sxx * dir.x + mxz * dir.z;
    const y = syy * dir.y + myz * dir.z;
    const z = dir.z;
    const len = Math.sqrt(x * x + y * y + z * z);
    return new THREE.Vector3(x / len, y / len, z / len);
  }

  // 仅变换不归一化 (用于保持面光源高度)
  function applyM_unnormalized(dir) {
    const sxx = state.sxx, syy = state.syy, mxz = state.mxz, myz = state.myz;
    const x = sxx * dir.x + mxz * dir.z;
    const y = syy * dir.y + myz * dir.z;
    const z = dir.z;
    return new THREE.Vector3(x, y, z);
  }

  // ----- 更新渲染 -----
  function updateAll() {
    const M_inv = buildInvM();

    // 1. 更新球面颜色
    const pos = sphereGeom.attributes.position.array;
    const col = sphereGeom.attributes.color.array;
    let maxD = 0;
    const dvals = new Float32Array(pos.length / 3);
    for (let i = 0; i < pos.length; i += 3) {
      const d = evalLTC(positionsRef[i], positionsRef[i + 1], positionsRef[i + 2], M_inv);
      dvals[i / 3] = d;
      if (d > maxD) maxD = d;
    }
    if (maxD < 1e-8) maxD = 1e-8;

    for (let i = 0; i < pos.length; i += 3) {
      pos[i] = positionsRef[i]; pos[i + 1] = positionsRef[i + 1]; pos[i + 2] = positionsRef[i + 2];
      const c = colormap(dvals[i / 3] / maxD);
      col[i] = c[0]; col[i + 1] = c[1]; col[i + 2] = c[2];
    }
    sphereGeom.attributes.position.needsUpdate = true;
    sphereGeom.attributes.color.needsUpdate = true;

    // 2. 更新射线
    const LINE_EXT = 1.04;
    for (let k = 0; k < NUM_SAMPLES; k++) {
      const ltcDir = applyM(cosineSamples[k]);
      const arr = sampleLines[k].geometry.attributes.position.array;
      arr[0] = 0; arr[1] = 0; arr[2] = 0;
      arr[3] = ltcDir.x * LINE_EXT; arr[4] = ltcDir.y * LINE_EXT; arr[5] = ltcDir.z * LINE_EXT;
      sampleLines[k].geometry.attributes.position.needsUpdate = true;
      sampleDots[k].position.set(ltcDir.x * LINE_EXT, ltcDir.y * LINE_EXT, ltcDir.z * LINE_EXT);
    }

    // 3. 更新面光源
    const lightPos = lightGeom.attributes.position.array;
    for (let i = 0; i < 4; i++) {
      const tp = applyM_unnormalized(lightBasePoints[i]);
      lightPos[i*3] = tp.x; lightPos[i*3+1] = tp.y; lightPos[i*3+2] = tp.z;

      const carr = connLines[i].geometry.attributes.position.array;
      carr[0] = 0; carr[1] = 0; carr[2] = 0;
      carr[3] = tp.x; carr[4] = tp.y; carr[5] = tp.z;
      connLines[i].geometry.attributes.position.needsUpdate = true;
    }
    lightGeom.attributes.position.needsUpdate = true;

    // 4. 更新参考方块
    const cubePos = cubeGeom.attributes.position.array;
    const sxx = state.sxx, syy = state.syy, mxz = state.mxz, myz = state.myz;
    for (let i = 0; i < cubePos.length; i += 3) {
      const x = cubeRef[i], y = cubeRef[i + 1], z = cubeRef[i + 2];
      cubePos[i]     = sxx * x + mxz * z;
      cubePos[i + 1] = syy * y + myz * z;
      cubePos[i + 2] = z;
    }
    cubeGeom.attributes.position.needsUpdate = true;
    cubeGeom.computeVertexNormals();
    cubeGeom.computeBoundingSphere();

    scene.remove(cubeEdges);
    cubeEdges.geometry.dispose();
    cubeEdges = new THREE.LineSegments(new THREE.EdgesGeometry(cubeGeom), cubeEdgesMat);
    cubeEdges.position.copy(cubeAnchor);
    cubeEdges.visible = document.getElementById('ltc-toggle-box').checked;
    scene.add(cubeEdges);
  }

  // ----- UI 绑定 -----
  const sliders = [
    { id: 'ltc-slider-sxx', valId: 'ltc-val-sxx', key: 'sxx' },
    { id: 'ltc-slider-syy', valId: 'ltc-val-syy', key: 'syy' },
    { id: 'ltc-slider-mxz', valId: 'ltc-val-mxz', key: 'mxz' },
    { id: 'ltc-slider-myz', valId: 'ltc-val-myz', key: 'myz' }
  ];

  function updateMatInfo() {
    document.getElementById('ltc-matrix-info').textContent =
      `M = [[${state.sxx.toFixed(2)}, 0.00, ${state.mxz.toFixed(2)}], [0.00, ${state.syy.toFixed(2)}, ${state.myz.toFixed(2)}], [0.00, 0.00, 1.00]]`;
  }

  sliders.forEach(s => {
    const el = document.getElementById(s.id);
    const valEl = document.getElementById(s.valId);
    el.addEventListener('input', () => {
      state[s.key] = parseFloat(el.value);
      valEl.textContent = state[s.key].toFixed(2);
      updateAll();
      updateMatInfo();
    });
  });

  const presets = {
    cosine: { sxx: 1.0, syy: 1.0, mxz: 0.0, myz: 0.0 },
    rough:  { sxx: 0.3, syy: 0.3, mxz: 0.0, myz: 0.0 },
    aniso:  { sxx: 0.8, syy: 0.2, mxz: 0.0, myz: 0.0 },
    skew:   { sxx: 1.0, syy: 1.0, mxz: 0.7, myz: 0.0 },
    full:   { sxx: 0.5, syy: 0.3, mxz: 0.4, myz: -0.2 }
  };

  document.querySelectorAll('#ltc-distribution-widget .ltc-preset-row button').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#ltc-distribution-widget .ltc-preset-row button')
        .forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      Object.assign(state, presets[btn.dataset.preset]);
      sliders.forEach(s => {
        document.getElementById(s.id).value = state[s.key];
        document.getElementById(s.valId).textContent = state[s.key].toFixed(2);
      });
      updateAll();
      updateMatInfo();
    });
  });

  // Toggles 逻辑
