```c UvToTransmittanceLutParams.hlsl
void UvToTransmittanceLutParams(float bottomRadius, float topRadius, float2 uv, out float mu, out float r)
{
    float x_mu = uv.x;
    float x_r = uv.y;
    float H = sqrt(max(0.0f, topRadius * topRadius - bottomRadius * bottomRadius));

    float rho = H * x_r;
    float rho2 = rho * rho;
    r = sqrt(max(0.0f, rho2 + bottomRadius * bottomRadius));

    float d_min = topRadius - r;
    float d_max = rho + H;
    float d = d_min + x_mu * (d_max - d_min);

    float denom = 2.0 * r * d + 1e-6;          // 防止除零
    float mu_raw = (H*H - rho2 - d*d) *rcp(denom); // 公式处理 d==0 时也稳定

    mu = saturate(mu_raw * 0.5 + 0.5) * 2.0 - 1.0; // 将 mu 映射回 [-1, 1]
}

float2 GetTransmittanceLutUV(float bottomRadius, float topRadius, float mu, float r)
{
    float H =sqrt(topRadius *topRadius -bottomRadius *bottomRadius);

    float rho2 = r*r - bottomRadius*bottomRadius;
    float rho  = sqrt(max(rho2, 0.0));

    float discriminant =  r * r *(mu * mu -1.0f) + topRadius * topRadius;
    float d =max(0.0f,(-r *mu +sqrt(discriminant)));

    float d_min = topRadius - r;
    float d_max = rho + H;

    float x_mu = saturate((d - d_min) * rcp(d_max - d_min));
    float x_r = saturate(rho * rcp(H));

    return  float2( x_mu, x_r );
}

```



```c CSTransmittanceLUT.compute
[numthreads(8, 8, 1)]
void CSTransmittanceLUT (uint3 id : SV_DispatchThreadID)
{
  // 检查线程是否在纹理范围内
  if (id.x >= _Width || id.y >= _Height)
    return;

  // 计算 UV 坐标 [0, 1]
  // 在像素中心采样
  float2 uv = (float2(id.xy) + 0.5) / float2(_Width, _Height);

  // 获取大气参数
  AtmosphereParameter param = GetAtmosphereParameter();

  float bottomRadius = param.PlanetRadius;
  float topRadius = param.PlanetRadius + param.AtmosphereHeight;

  // 计算当前 UV 对应的 cos_theta (mu) 和 height (r)
  float cos_theta = 0.0;
  float r = 0.0;
  UvToTransmittanceLutParams(bottomRadius, topRadius, uv, cos_theta, r);

  // 构建射线
  float sin_theta = sqrt(saturate(1.0 - cos_theta * cos_theta));
  float3 viewDir = float3(sin_theta, cos_theta, 0);
  float3 eyePos = float3(0, r, 0);

  // 光线和大气层外边界求交
  float dis = RayIntersectSphere(float3(0, 0, 0), topRadius, eyePos, viewDir);

  // 如果没有交点（不应该发生），返回白色（无吸收）
  if (dis < 0.0)
  {
    TransmittanceLUT[id.xy] = float4(1, 1, 1, 1);
    return;
  }

  float3 hitPoint = eyePos + viewDir * dis;

  // Raymarch 计算 Transmittance
  float3 transmittance = Transmittance(param, eyePos, hitPoint);

  // 写入结果
  // Alpha 通道设为 1（不透明）
  TransmittanceLUT[id.xy] = float4(transmittance, 1.0);
}
```


#### Multi-Scattering LUT
[[Hillaire 2020]](https://sebh.github.io/publications/)<font style="color:rgb(25, 27, 31);">论文作者在计算Multiple Scattering时，认为高阶散射非常低频，从此出发使用了一些简化，包括：</font>

1. <u><font style="color:rgb(25, 27, 31);">大于等于2阶的散射，将Rayleigh散射和Mie散射视为为各向同性的散射</font></u>
2. <u><font style="color:rgb(25, 27, 31);">计算某点的大于2阶的Scattering时，认为该点周围任意一点的Illuminance与其相同</font></u>

<font style="color:rgb(25, 27, 31);">第一点，对于1阶散射，我们认为Rayleigh、Mie散射是正常的，但是在之后的阶数，我们认为</font><u><font style="color:rgb(25, 27, 31);">相位函数对于任何方向都是相同的值</font></u><font style="color:rgb(25, 27, 31);"> </font>$ 1.0/(4.0 *M_{\pi}) $<font style="color:rgb(25, 27, 31);"> 。于是我们计算Multiple Scattering LUT时，LUT的维数就少了2维。</font>

<font style="color:rgb(25, 27, 31);">第二点，在计算某点的Scattering时，</font><u><font style="color:rgb(25, 27, 31);">空间中任意一点的某一阶的Scattering都视作和该点相同</font></u><font style="color:rgb(25, 27, 31);">。因为参与计算的点需要与该点有</font>**<font style="color:rgb(25, 27, 31);">视线链接 [</font>**<font style="color:rgb(25, 27, 31);">Line of sight</font>**<font style="color:rgb(25, 27, 31);">]</font>**<font style="color:rgb(25, 27, 31);">，从整个地球的视角来看确实是Neighboring points。这一条近似看上去是非常粗略的，但是看起来是有效的。</font>

<font style="color:rgb(25, 27, 31);">实际流程中，Multiple Scattering LUT的计算可以一个pass输出到一张32*32的2D LUT完成。只需要2D的原因是因为上述简化中我们使用了各向同性Phase Function，不需要存储相机跟光照方向的关系，只需要存储不同高度、不同光照角度的情况即可。</font>

<font style="color:rgb(25, 27, 31);">在pass中，论文中提到，首先计算</font>$ L_{2_{nd}order} $<font style="color:rgb(25, 27, 31);">，这里的</font>$ L_{2_{nd}order} $<font style="color:rgb(25, 27, 31);">是在LUT当前像素代表的点上，对整个球面做 </font><u><font style="color:rgb(25, 27, 31);">Phase Function * Luminance的积分</font></u><font style="color:rgb(25, 27, 31);">得到，记为</font>$ G_2 $<font style="color:rgb(25, 27, 31);"> 。具体计算方式公式为如下：</font>

 $$ G_2 = \int_{\Omega}L_1(x_s,-\omega)p_ud\omega\tag{1} $$ 

 $$ L_1=T(x,p)L_0(p,v)+\int_{t=0}^{||p-x||}\sigma_s(x)T(x,x-tv)S(x,\omega_s)p_uE_Idt\tag{2} $$ 

<font style="color:rgb(25, 27, 31);">其中</font>$ L_1 $<font style="color:rgb(25, 27, 31);">计算部分的</font>$ T(x,p)L_0(p,v) $<font style="color:rgb(25, 27, 31);">为地面的反射光，</font>$ S(x,w_s) $<font style="color:rgb(25, 27, 31);">为阳光到达x点的照度。这里的</font>$ E_{I} $<font style="color:rgb(25, 27, 31);">是一个单位值的阳光照度，实际的照度数值是在最后乘上去的。</font>

##### <font style="color:rgb(25, 27, 31);">转移函数 </font>$ f_{ms} $
<font style="color:rgb(25, 27, 31);">第二步，在上述计算完毕后，计算当前像素的Transfer Function</font>$ f_{ms} $<font style="color:rgb(25, 27, 31);">[ 不是真的Function，对于当前计算的像素来说是一个固定的数值 ]，可以将</font>$ G_n $<font style="color:rgb(25, 27, 31);">转换为更高阶的Scattering。论文中直接给出了Transfer Function的计算方法：</font>

 $$ f_{ms}=\int_{\Omega}L_f(x_s,-\omega)p_u d\omega\tag{3} $$ 

 $$L_f(x,v)=\int_{t=0}^{||p-x||}\sigma_s(x)T(x,x-tv)1dt\tag{4}$$ 

<font style="color:rgb(25, 27, 31);">使用 </font>$ f_{ms} $<font style="color:rgb(25, 27, 31);">，有：</font>

 $$ G_{n+1} = G_n*f_{ms}\tag{5} $$ 

<font style="color:rgb(25, 27, 31);">这里可能会对</font>$ f_{ms} $<font style="color:rgb(25, 27, 31);">的计算稍微感到迷惑。其实这是在上述1、2点简化的情况下，将原本的计算散射的式子做了化简的结果。我们可以简单地推导一下。首先是传统的</font>$ G_n $<font style="color:rgb(25, 27, 31);">的计算方法：</font>

 $$  G_n(x,v) = \int_{\Omega}L_{n-1}(x,-\omega)pd\omega\tag{6}  $$ 

 $$  L_{n-1}(x,v)=\int_{t=0}^{||p-x||}\sigma_s(x)T(x,x-tv)G_{n-1}(x-tv,-v)dt\tag{7}  $$ 

<font style="color:rgb(25, 27, 31);">根据简化1、2，我们认为在计算当前像素时，</font>$ G_{n-1} $<font style="color:rgb(25, 27, 31);">在任意一点都是固定的数值，</font>$ L_{n-1} $<font style="color:rgb(25, 27, 31);">式可以改写为：</font>

 $$ L_{n-1}(x,v)=G_{n-1}\int_{t=0}^{||p-x||}\sigma_s(x)T(x,x-tv)dt\tag{8} $$ 

<font style="color:rgb(25, 27, 31);">即</font>$ L_{n-1}(x,v)=G_{n-1}L_f(x,v) $<font style="color:rgb(25, 27, 31);">，再代回去(6)，两边同除</font>$ G_{n-1} $<font style="color:rgb(25, 27, 31);">，将</font>$ p $<font style="color:rgb(25, 27, 31);">替换为</font>$ p_u $<font style="color:rgb(25, 27, 31);">，得：</font>

 $$ G_n / G_{n-1} = \int_{\Omega}L_f(x,-\omega)p_ud\omega=f_{ms}\tag{9} $$ 

<font style="color:rgb(25, 27, 31);">可以发现，相比（2）式，（7）式中省去了</font><u>**<font style="color:rgb(25, 27, 31);">地面反射</font>**</u><font style="color:rgb(25, 27, 31);">。作者表示确实是</font><u><font style="color:rgb(25, 27, 31);">忽略了多重散射照射到地面形成反射的贡献</font></u><font style="color:rgb(25, 27, 31);">,不过保留的话也没办法化简出这么一个 </font>$ f_{ms} $<font style="color:rgb(25, 27, 31);">。好在这一部分贡献并不是很多，对最终结果影响不大。</font>

##### <font style="color:rgb(25, 27, 31);">多重散射结果</font>
<font style="color:rgb(25, 27, 31);">有了</font>$ f_{ms} $<font style="color:rgb(25, 27, 31);">，我们就可以计算任意</font>$ G_n $<font style="color:rgb(25, 27, 31);">了。接下去就是论文</font><u>**<font style="color:rgb(25, 27, 31);">独到</font>**</u><font style="color:rgb(25, 27, 31);">的地方。</font>

<font style="color:rgb(25, 27, 31);">根据数学公式，因为</font>$ f_{ms} $<font style="color:rgb(25, 27, 31);">小于1.0，我们可以直接得到无穷阶数的</font>$ G_n $<font style="color:rgb(25, 27, 31);">之和：</font>

 $$ F_{ms}=1+f_{ms}+f^2_{ms}+f^3_{ms}+...\tag{10}=1/(1-f_{ms}) $$ 

 $$ G_2+G_3+G_4+...=G_2*F_{ms}\tag{11}=\Psi_{ms} $$ 

<font style="color:rgb(25, 27, 31);">最后，就可以将</font>$ \Psi_{ms} $<font style="color:rgb(25, 27, 31);">写入二维的LUT中保存了。之后采样这张LUT，就可以得到2阶及以上阶数的散射之和。</font>

