  function initIntegrator() {
    var ce = document.getElementById('ms-canvas-euler');
    var cv = document.getElementById('ms-canvas-verlet');
    if (!ce || !cv) return;
    var ctxE = ce.getContext('2d'), ctxV = cv.getContext('2d');
    var W = ce.width, H = ce.height;
    var dt = 0.08, k = 25, m = 1, steps = 220;

    function simulate() {
      // Forward Euler (严格的显式实现)
      var xE = [], vE = 0, xE_curr = 1;
      xE.push(xE_curr);
      for (var i = 1; i < steps; i++) {
        var aE = -(k / m) * xE_curr;
        // 先用老速度更新位置，再更新速度（这是真正的 Explicit Euler）
        var next_x = xE_curr + vE * dt;
        var next_v = vE + aE * dt;
        xE_curr = next_x;
        vE = next_v;
        xE.push(xE_curr);
      }

      // Verlet
      var xV = [1, 1];
      for (var j = 0; j < steps - 2; j++) {
        var xn = xV[xV.length - 1];
        var xp = xV[xV.length - 2];
        var aV = -(k / m) * xn;
        xV.push(2 * xn - xp + aV * dt * dt);
      }
      return [xE, xV];
    }

    function drawTrace(ctx, data, color) {
      ctx.clearRect(0, 0, W, H);
      ctx.strokeStyle = '#eee'; ctx.lineWidth = 1;
      for (var y = 0; y <= H; y += H / 4) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
      }
      ctx.strokeStyle = '#bbb'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(0, H / 2); ctx.lineTo(W, H / 2); ctx.stroke();

      var clamp = 4;
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      var diverged = false;
      for (var i = 0; i < data.length; i++) {
        var px = (i / (data.length - 1)) * W;
        var val = data[i];
        if (!isFinite(val) || Math.abs(val) > clamp) { diverged = true; val = Math.sign(val) * clamp; }
        var py = H / 2 - val * (H / 2 - 8) / clamp;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.stroke();
      if (diverged) {
        ctx.fillStyle = 'rgba(231, 76, 60, 0.85)';
        ctx.font = 'bold 12px -apple-system, sans-serif';
        ctx.fillText('⚠ 振幅超过 ±4,系统已发散', 8, 18);
