      html += '<line x1="' + (a.x + a.w) + '" y1="' + (a.y + a.h / 2) + '" x2="' + (b.x - 4) + '" y2="' + (b.y + b.h / 2) + '" stroke="#888" stroke-width="2" marker-end="url(#ms-arrow)"/>';
