    html += '<path d="M ' + (last.x + last.w / 2) + ' ' + (last.y + last.h) + ' Q ' + (last.x + last.w / 2) + ' 200 ' + (first.x + first.w / 2 + 60) + ' 200 Q ' + (first.x - 30) + ' 200 ' + (first.x - 8) + ' ' + (first.y + first.h / 2) + '" stroke="#888" stroke-width="2" stroke-dasharray="4 3" fill="none" marker-end="url(#ms-arrow)"/>';
    html += '<text x="360" y="215" text-anchor="middle" font-size="11" fill="#888">Next Frame</text>';
    nodes.forEach(function (n) {
      html += '<rect x="' + n.x + '" y="' + n.y + '" width="' + n.w + '" height="' + n.h + '" rx="8" fill="#fff" stroke="' + n.color + '" stroke-width="2"/>';
      html += '<text x="' + (n.x + n.w / 2) + '" y="' + (n.y + 22) + '" text-anchor="middle" font-size="13" font-weight="600" fill="#222">' + n.label + '</text>';
      html += '<text x="' + (n.x + n.w / 2) + '" y="' + (n.y + 42) + '" text-anchor="middle" font-size="11" fill="#666">' + n.sub + '</text>';
    });
    html += '<text x="360" y="30" text-anchor="middle" font-size="14" font-weight="600" fill="#333">PBD Per-Frame Pipeline</text>';
    html += '<text x="360" y="50" text-anchor="middle" font-size="11" fill="#888">每个 Substep 内部:② 步骤可重复 5 ~ 20 次以提升刚度</text>';
    svg.innerHTML = html;
  }

  // ============================================================
  // Demo 4: PBD 距离约束交互 Canvas (修复了权重分配 Bug)
  // ============================================================
  function initPBD() {
    var canvas = document.getElementById('ms-pbd-canvas');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    var W = canvas.width, H = canvas.height;
    var N = 12, restLen = 22, startX = W / 2, startY = 30;
    var iterations = 5, gravity = 0.4, retainV = 0.99, dragIdx = -1;

    var particles = [];
    function reset() {
      particles = [];
      for (var i = 0; i < N; i++) {
        particles.push({ x: startX, y: startY + i * restLen, ox: startX, oy: startY + i * restLen, pinned: i === 0 });
      }
    }
    reset();

    function getMouse(e) {
      var rect = canvas.getBoundingClientRect();
      var sx = canvas.width / rect.width, sy = canvas.height / rect.height;
      var t = (e.touches && e.touches[0]) || e;
      return { x: (t.clientX - rect.left) * sx, y: (t.clientY - rect.top) * sy };
    }
    function onDown(e) {
      var m = getMouse(e); var minD = 22, idx = -1;
      for (var i = 0; i < N; i++) {
        var dx = particles[i].x - m.x, dy = particles[i].y - m.y;
        var d = Math.sqrt(dx * dx + dy * dy);
        if (d < minD) { minD = d; idx = i; }
      }
      dragIdx = idx;
      e.preventDefault();
    }
    function onMove(e) {
      if (dragIdx < 0) return;
      var m = getMouse(e);
      particles[dragIdx].x = m.x; particles[dragIdx].y = m.y;
      e.preventDefault();
    }
    function onUp() { dragIdx = -1; }
    canvas.addEventListener('mousedown', onDown); canvas.addEventListener('mousemove', onMove); window.addEventListener('mouseup', onUp);
    canvas.addEventListener('touchstart', onDown, { passive: false }); canvas.addEventListener('touchmove', onMove, { passive: false }); canvas.addEventListener('touchend', onUp);

    function step() {
      for (var i = 0; i < N; i++) {
        var p = particles[i];
        if (p.pinned) continue;
        if (i === dragIdx) { p.ox = p.x; p.oy = p.y; continue; }
        var vx = (p.x - p.ox) * retainV, vy = (p.y - p.oy) * retainV;
        p.ox = p.x; p.oy = p.y;
        p.x += vx; p.y += vy + gravity;
      }
      for (var it = 0; it < iterations; it++) {
        for (var i2 = 0; i2 < N - 1; i2++) {
          var a = particles[i2], b = particles[i2 + 1];
          var dx = b.x - a.x, dy = b.y - a.y;
          var d = Math.sqrt(dx * dx + dy * dy);
          if (d < 1e-6) continue;

          // 修复：遵循 PBD 质量倒数加权法则，避免硬编码 0.5
          var w1 = (a.pinned || i2 === dragIdx) ? 0 : 1;
          var w2 = (b.pinned || (i2 + 1) === dragIdx) ? 0 : 1;
          var sumW = w1 + w2;

          if (sumW > 0) {
            var diff = (d - restLen) / (d * sumW);
            var cx = dx * diff, cy = dy * diff;
            if (w1 > 0) { a.x += cx; a.y += cy; }
            if (w2 > 0) { b.x -= cx; b.y -= cy; }
          }
        }
      }
    }
    function draw() {
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      ctx.strokeStyle = '#4263eb'; ctx.lineWidth = 2; ctx.beginPath();
      for (var i = 0; i < N - 1; i++) { ctx.moveTo(particles[i].x, particles[i].y); ctx.lineTo(particles[i + 1].x, particles[i + 1].y); }
      ctx.stroke();
      for (var j = 0; j < N; j++) {
        var p = particles[j];
        var color = p.pinned ? '#e74c3c' : (j === dragIdx ? '#f39c12' : '#27ae60');
        ctx.fillStyle = color; ctx.beginPath(); ctx.arc(p.x, p.y, 7, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
      }
    }
    function loop() { step(); draw(); requestAnimationFrame(loop); }

    var slider = document.getElementById('ms-iter-slider'), val = document.getElementById('ms-iter-val');
    slider.addEventListener('input', function (e) { iterations = parseInt(e.target.value); val.textContent = iterations; });
    document.getElementById('ms-pbd-reset').addEventListener('click', reset);
    loop();
  }

  // ============================================================
  // Demo 5: 红黑图着色 SVG
  // ============================================================
  function initColoring() {
    var svg = document.getElementById('ms-coloring');
    if (!svg) return;
    var N = 11, W = 720, oy = 70, spacing = (W - 80) / (N - 1), ox = 40;
    var phaseEl = document.getElementById('ms-color-phase');

    function render(activeColor) {
      var html = '';
      for (var i = 0; i < N - 1; i++) {
        var p1x = ox + i * spacing, p2x = ox + (i + 1) * spacing, isRed = i % 2 === 0;
        var c = isRed ? '#e74c3c' : '#1f2937', active = (activeColor === 'red' && isRed) || (activeColor === 'black' && !isRed);
        var w = active ? 5 : 2.5, op = (activeColor && !active) ? 0.18 : 1;
        html += '<line x1="' + p1x + '" y1="' + oy + '" x2="' + p2x + '" y2="' + oy + '" stroke="' + c + '" stroke-width="' + w + '" opacity="' + op + '" stroke-linecap="round"/>';
        if (active) {
          var mx = (p1x + p2x) / 2;
          html += '<circle cx="' + mx + '" cy="' + oy + '" r="6" fill="#fff" stroke="' + c + '" stroke-width="2"><animate attributeName="r" values="4;10;4" dur="0.8s" repeatCount="indefinite"/></circle>';
        }
      }
      for (var j = 0; j < N; j++) {
        html += '<circle cx="' + (ox + j * spacing) + '" cy="' + oy + '" r="7" fill="#1f2937" stroke="#fff" stroke-width="2"/>';
        html += '<text x="' + (ox + j * spacing) + '" y="' + (oy + 25) + '" text-anchor="middle" font-size="10" fill="#888">' + j + '</text>';
      }
      html += '<text x="40" y="22" font-size="12" fill="#666">同色弹簧两两不共享顶点 → 可无锁并行</text><rect x="540" y="12" width="14" height="3" fill="#e74c3c"/><text x="558" y="18" font-size="11" fill="#666">Red Pass</text><rect x="620" y="12" width="14" height="3" fill="#1f2937"/><text x="638" y="18" font-size="11" fill="#666">Black Pass</text>';
      svg.innerHTML = html;
    }
    render(null);

    var btn = document.getElementById('ms-color-play'), playing = false;
    btn.addEventListener('click', function () {
      if (playing) return;
      playing = true; btn.disabled = true;
      phaseEl.textContent = '▶ 求解 Red Pass (5 条并行)'; render('red');
      setTimeout(function () {
        phaseEl.textContent = '▶ 求解 Black Pass (5 条并行)'; render('black');
        setTimeout(function () {
          phaseEl.textContent = '✓ 一轮完成'; render(null); btn.disabled = false; playing = false;
        }, 1600);
      }, 1600);
    });
  }

  // ============================================================
  // Demo 6: Three.js 布料 (新增相机 OrbitControls 与交互互斥)
  // ============================================================
  function initCloth() {
    var container = document.getElementById('ms-cloth-container');
    if (!container || typeof THREE === 'undefined') return;

    var W = container.clientWidth || 600, H = container.clientHeight || 400;
    var scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf5f5f7);

    var camera = new THREE.PerspectiveCamera(50, W / H, 0.1, 100);
    // 初始机位稍微调整，提供一个较好的俯视斜角
    camera.position.set(5, 4, 8); 

    var renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(W, H); 
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // ================= 新增：OrbitControls =================
    var controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;       // 开启丝滑阻尼感
    controls.dampingFactor = 0.05;
    controls.maxPolarAngle = Math.PI / 2 + 0.2; // 限制视角不要钻到地底太深
    controls.target.set(0, 0, 0);        // 聚焦中心
    // =======================================================

    var l1 = new THREE.DirectionalLight(0xffffff, 0.85); l1.position.set(4, 4, 5); scene.add(l1);
    var l2 = new THREE.DirectionalLight(0xffffff, 0.4); l2.position.set(-4, -2, 3); scene.add(l2);
    scene.add(new THREE.AmbientLight(0x808080));

    var floorY = -1.5;
    var gridHelper = new THREE.GridHelper(10, 10, 0xcccccc, 0xe0e0e0);
    gridHelper.position.y = floorY;
    scene.add(gridHelper);

    var windArrow = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(-3, 1.5, -2), 0, 0x00bcd4, 0.4, 0.3);
    windArrow.visible = false;
    scene.add(windArrow);

    var N = 16, size = 4.5, spacing = size / (N - 1), rest = spacing, restD = spacing * Math.sqrt(2);
    var particles = [];

    function resetParticles() {
      for (var i = 0; i < N; i++) {
        for (var j = 0; j < N; j++) {
          var k = i * N + j;
          var x = (j - (N - 1) / 2) * spacing;
          var z = (i - (N - 1) / 2) * spacing;
          var y = 1.8; 

          if(!particles[k]) {
            particles.push({ pos: new THREE.Vector3(), old: new THREE.Vector3(), pinned: false });
          }
          particles[k].pos.set(x, y, z);
          particles[k].old.set(x, y, z);
          particles[k].pinned = (i === 0) && (j === 0 || j === N - 1);
        }
      }
    }
    resetParticles();

    function id(i, j) { return i * N + j; }
    var springs = [];
    for (var i2 = 0; i2 < N; i2++) {
      for (var j2 = 0; j2 < N; j2++) {
        if (j2 < N - 1) springs.push({ a: id(i2, j2), b: id(i2, j2 + 1), r: rest });
        if (i2 < N - 1) springs.push({ a: id(i2, j2), b: id(i2 + 1, j2), r: rest });
        if (i2 < N - 1 && j2 < N - 1) springs.push({ a: id(i2, j2), b: id(i2 + 1, j2 + 1), r: restD });
        if (i2 < N - 1 && j2 > 0) springs.push({ a: id(i2, j2), b: id(i2 + 1, j2 - 1), r: restD });
      }
    }

    var geometry = new THREE.BufferGeometry();
    var positions = new Float32Array(N * N * 3);
    var indices = [];
    for (var i3 = 0; i3 < N - 1; i3++) {
      for (var j3 = 0; j3 < N - 1; j3++) {
        indices.push(id(i3, j3), id(i3 + 1, j3), id(i3, j3 + 1));
        indices.push(id(i3 + 1, j3), id(i3 + 1, j3 + 1), id(i3, j3 + 1));
      }
    }
    geometry.setIndex(indices);
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

    function updateMesh() {
      var arr = geometry.attributes.position.array;
      for (var k = 0; k < particles.length; k++) {
        arr[k*3] = particles[k].pos.x; arr[k*3+1] = particles[k].pos.y; arr[k*3+2] = particles[k].pos.z;
      }
      geometry.attributes.position.needsUpdate = true;
      geometry.computeVertexNormals();
    }
    updateMesh(); 

    var material = new THREE.MeshLambertMaterial({ color: 0x4263eb, side: THREE.DoubleSide });
    var mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    var wireMaterial = new THREE.MeshBasicMaterial({ color: 0x1a3eb8, wireframe: true, transparent: true, opacity: 0.3 });
    var wireMesh = new THREE.Mesh(geometry, wireMaterial);
    wireMesh.visible = false;
    scene.add(wireMesh);

    var sphere = { pos: new THREE.Vector3(0, -0.2, 0), radius: 0.8 };
    var sMesh = new THREE.Mesh(new THREE.SphereGeometry(sphere.radius, 32, 32), new THREE.MeshLambertMaterial({ color: 0xe74c3c }));
    sMesh.position.copy(sphere.pos); scene.add(sMesh);

    var raycaster = new THREE.Raycaster(), mouseV = new THREE.Vector2();
    var dragIdx = -1, dragPlane = new THREE.Plane(), dragPt = new THREE.Vector3();
    var dom = renderer.domElement;

    dom.addEventListener('pointerdown', function (e) {
      var rect = dom.getBoundingClientRect();
      var cx = e.clientX !== undefined ? e.clientX : e.touches[0].clientX;
      var cy = e.clientY !== undefined ? e.clientY : e.touches[0].clientY;
      mouseV.x = ((cx - rect.left) / rect.width) * 2 - 1; mouseV.y = -((cy - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mouseV, camera);
      var bestD = 0.3, bestI = -1;
      for (var i = 0; i < particles.length; i++) {
        var d = raycaster.ray.distanceSqToPoint(particles[i].pos);
        if (d < bestD) { bestD = d; bestI = i; }
      }
      if (bestI >= 0) {
        dragIdx = bestI; 

        // ================= 核心互斥逻辑 =================
        controls.enabled = false; // 点中布料时，禁用相机旋转
        // ================================================

        var camDir = new THREE.Vector3(); camera.getWorldDirection(camDir); 
