      }
    });

    dom.addEventListener('pointermove', function (e) {
      if (dragIdx < 0) return;
      var rect = dom.getBoundingClientRect();
      var cx = e.clientX !== undefined ? e.clientX : e.touches[0].clientX;
      var cy = e.clientY !== undefined ? e.clientY : e.touches[0].clientY;
      mouseV.x = ((cx - rect.left) / rect.width) * 2 - 1; mouseV.y = -((cy - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mouseV, camera);
      if (raycaster.ray.intersectPlane(dragPlane, dragPt)) { particles[dragIdx].pos.copy(dragPt); particles[dragIdx].old.copy(dragPt); }
    });

    function endDrag() { 
        dragIdx = -1; 
        controls.enabled = true; // 松开鼠标，恢复相机旋转控制
    }
    dom.addEventListener('pointerup', endDrag); dom.addEventListener('pointerleave', endDrag);

    var gravity = new THREE.Vector3(0, -9.8, 0), dt = 1 / 60, damping = 0.99, iters = 5;
    var windForce = 0, windDir = new THREE.Vector3(Math.cos(Math.PI/4), 0, Math.sin(Math.PI/4)), windVelocity = new THREE.Vector3();
    var aeroCoefficient = 0.5;

    function step() {
      var normals = geometry.attributes.normal.array;
      for (var i = 0; i < particles.length; i++) {
        var p = particles[i];
        if (p.pinned || i === dragIdx) continue;
        var vel = new THREE.Vector3().subVectors(p.pos, p.old).divideScalar(dt);
        var n = new THREE.Vector3(normals[i*3], normals[i*3+1], normals[i*3+2]);
        var vRel = new THREE.Vector3().subVectors(windVelocity, vel);
        var vn = vRel.dot(n); 
        var fAero = n.multiplyScalar(vn * aeroCoefficient);
        var acc = gravity.clone().add(fAero);
        var tmp = new THREE.Vector3().subVectors(p.pos, p.old).multiplyScalar(damping);
        p.old.copy(p.pos);
        p.pos.add(tmp);
        p.pos.addScaledVector(acc, dt * dt);
      }

      for (var it = 0; it < iters; it++) {
        for (var s = 0; s < springs.length; s++) {
          var sp = springs[s], a = particles[sp.a], b = particles[sp.b];
          var dx = b.pos.x - a.pos.x, dy = b.pos.y - a.pos.y, dz = b.pos.z - a.pos.z;
          var d2 = dx * dx + dy * dy + dz * dz; if (d2 < 1e-12) continue;
          var d = Math.sqrt(d2);
          var w1 = (a.pinned || sp.a === dragIdx) ? 0 : 1;
          var w2 = (b.pinned || sp.b === dragIdx) ? 0 : 1;
          var sumW = w1 + w2;
          if(sumW > 0) {
              var diff = (d - sp.r) / (d * sumW);
              var cx = dx * diff, cy = dy * diff, cz = dz * diff;
              if (w1 > 0) { a.pos.x += cx; a.pos.y += cy; a.pos.z += cz; }
              if (w2 > 0) { b.pos.x -= cx; b.pos.y -= cy; b.pos.z -= cz; }
          }
        }

        for (var c = 0; c < particles.length; c++) {
          var pp = particles[c];
          if (pp.pinned || c === dragIdx) continue;
          var ddx = pp.pos.x - sphere.pos.x, ddy = pp.pos.y - sphere.pos.y, ddz = pp.pos.z - sphere.pos.z;
          var dd = Math.sqrt(ddx * ddx + ddy * ddy + ddz * ddz);
          if (dd < sphere.radius && dd > 1e-6) {
            var inv = (sphere.radius + 0.1) / dd; 
            pp.pos.x = sphere.pos.x + ddx * inv; 
            pp.pos.y = sphere.pos.y + ddy * inv; 
            pp.pos.z = sphere.pos.z + ddz * inv;
          }
          if (pp.pos.y < floorY) {
            pp.pos.y = floorY;
