    }

    var fpsEl = document.getElementById('ms-cloth-fps'), lastT = performance.now(), frames = 0, accT = 0;

    function animate() {
      // 在动画循环中必须更新 controls，以保证 damping 阻尼效果生效
      controls.update(); 

      step(); 
      updateMesh(); 
      renderer.render(scene, camera);
      var now = performance.now(); accT += now - lastT; lastT = now; frames++;
