        windArrow.setDirection(windDir);
        windArrow.setLength(1 + windForce * 0.15);
        windArrow.visible = true;
      } else {
        windArrow.visible = false;
      }
    }

    document.getElementById('ms-wind-dir').addEventListener('input', function(e) {
      var angle = e.target.value * Math.PI / 180;
      windDir.set(Math.cos(angle), 0, Math.sin(angle));
      updateWindVisual();
    });
    document.getElementById('ms-wind-force').addEventListener('input', function(e) {
      windForce = parseFloat(e.target.value);
      updateWindVisual();
    });
    document.getElementById('ms-cloth-reset').addEventListener('click', resetParticles);
    document.getElementById('ms-cloth-drop').addEventListener('click', function () {
      for (var i = 0; i < particles.length; i++) { particles[i].pinned = false; }
    });
    document.getElementById('ms-cloth-toggle-wire').addEventListener('click', function () {
      wireMesh.visible = !wireMesh.visible;
    });

    window.addEventListener('resize', function () {
      var w = container.clientWidth || 600, h = container.clientHeight || 400;
      renderer.setSize(w, h); camera.aspect = w / h; camera.updateProjectionMatrix();
    });
  }

